"use strict";
import { useMemo } from "react";
import { useReadContract } from "wagmi";
const RATIO_SCALE = 1000000n;
const V2_GAUGE_VIEW_ABI = [
  {
    inputs: [],
    name: "rewardRate",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "totalSupply",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const CL_GAUGE_VIEW_ABI = [
  {
    inputs: [],
    name: "rewardRate",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const CL_POOL_VIEW_ABI = [
  {
    inputs: [],
    name: "stakedLiquidity",
    outputs: [{ internalType: "uint128", name: "", type: "uint128" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "liquidity",
    outputs: [{ internalType: "uint128", name: "", type: "uint128" }],
    stateMutability: "view",
    type: "function"
  }
];
const ERC20_TOTAL_SUPPLY_ABI = [
  {
    inputs: [],
    name: "totalSupply",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
export function useGaugeApr({
  gaugeAddress,
  poolAddress,
  poolType,
  tvlUSD,
  abxPriceUSD,
  enabled = true
}) {
  const gaugeAddr = gaugeAddress?.toLowerCase();
  const poolAddr = poolAddress?.toLowerCase();
  const normalizedType = poolType?.toUpperCase();
  const isV3 = normalizedType === "V3" || normalizedType === "CL";
  const isV2 = normalizedType === "V2";
  const rewardRateQuery = useReadContract({
    address: gaugeAddr,
    abi: isV3 ? CL_GAUGE_VIEW_ABI : V2_GAUGE_VIEW_ABI,
    functionName: "rewardRate",
    enabled: enabled && Boolean(
      gaugeAddr && tvlUSD && tvlUSD > 0 && abxPriceUSD && abxPriceUSD > 0 && (isV3 && gaugeAddr || isV2)
    ),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  const v2TotalSupplyQuery = useReadContract({
    address: gaugeAddr,
    abi: V2_GAUGE_VIEW_ABI,
    functionName: "totalSupply",
    enabled: enabled && Boolean(isV2 && gaugeAddr),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  const v2PoolSupplyQuery = useReadContract({
    address: poolAddr,
    abi: ERC20_TOTAL_SUPPLY_ABI,
    functionName: "totalSupply",
    enabled: enabled && Boolean(isV2 && poolAddr),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  const v3StakedLiquidityQuery = useReadContract({
    address: poolAddr,
    abi: CL_POOL_VIEW_ABI,
    functionName: "stakedLiquidity",
    enabled: enabled && Boolean(isV3 && poolAddr),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  const v3TotalLiquidityQuery = useReadContract({
    address: poolAddr,
    abi: CL_POOL_VIEW_ABI,
    functionName: "liquidity",
    enabled: enabled && Boolean(isV3 && poolAddr),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  return useMemo(() => {
    const rewardRateRaw = rewardRateQuery.data;
    const rewardRatePerSecond = rewardRateRaw !== void 0 ? Number(rewardRateRaw) / 1e18 : void 0;
    let stakedTvlUSD;
    if (isV2 && v2TotalSupplyQuery.data && v2PoolSupplyQuery.data && typeof tvlUSD === "number") {
      const gaugeSupply = v2TotalSupplyQuery.data;
      const poolSupply = v2PoolSupplyQuery.data;
      if (gaugeSupply > 0n && poolSupply > 0n) {
        const ratioScaled = gaugeSupply * RATIO_SCALE / poolSupply;
        stakedTvlUSD = tvlUSD * (Number(ratioScaled) / Number(RATIO_SCALE));
      }
    } else if (isV3 && v3StakedLiquidityQuery.data && v3TotalLiquidityQuery.data && typeof tvlUSD === "number") {
      const stakedLiquidity = v3StakedLiquidityQuery.data;
      const totalLiquidity = v3TotalLiquidityQuery.data;
      if (stakedLiquidity > 0n && totalLiquidity > 0n) {
        const ratioScaled = stakedLiquidity * RATIO_SCALE / totalLiquidity;
        stakedTvlUSD = tvlUSD * (Number(ratioScaled) / Number(RATIO_SCALE));
      }
    }
    let aprPercent;
    if (rewardRatePerSecond !== void 0 && rewardRatePerSecond > 0 && stakedTvlUSD !== void 0 && stakedTvlUSD > 0 && abxPriceUSD && abxPriceUSD > 0) {
      const weeklyEmissionsABX = rewardRatePerSecond * 604800;
      const annualRewardsUSD = weeklyEmissionsABX * 52 * abxPriceUSD;
      aprPercent = annualRewardsUSD / stakedTvlUSD * 100;
    }
    return {
      aprPercent,
      rewardRatePerSecond,
      stakedTvlUSD,
      isLoading: rewardRateQuery.isFetching || v2TotalSupplyQuery.isFetching || v2PoolSupplyQuery.isFetching || v3StakedLiquidityQuery.isFetching || v3TotalLiquidityQuery.isFetching
    };
  }, [
    abxPriceUSD,
    isV2,
    isV3,
    rewardRateQuery.data,
    rewardRateQuery.isFetching,
    tvlUSD,
    v2PoolSupplyQuery.data,
    v2PoolSupplyQuery.isFetching,
    v2TotalSupplyQuery.data,
    v2TotalSupplyQuery.isFetching,
    v3StakedLiquidityQuery.data,
    v3StakedLiquidityQuery.isFetching,
    v3TotalLiquidityQuery.data,
    v3TotalLiquidityQuery.isFetching
  ]);
}
